import React, { useEffect, useRef, useState } from 'react';
import { Link } from 'react-router-dom';
import './Home.css';
import Img1 from '../assets/images/img1.jpeg';
import Img2 from '../assets/images/img2.jpeg';
import heroImage from '../assets/images/img3.jpeg'; // background image

const partners = [
  {
    name: 'Company A',
    logo: Img1,
    description: 'Company A specializes in smart home systems and automation protocols.',
    website: 'https://www.google.com',
  },
  {
    name: 'Company B',
    logo: Img2,
    description: 'Company B offers high-end IoT solutions and energy management tools.',
    website: 'https://www.youtube.com',
  },
];

function Home() {
  const [isVisible, setIsVisible] = useState(false);
  const partnersRef = useRef(null);
  const [partnersVisible, setPartnersVisible] = useState(false);

  useEffect(() => {
    window.scrollTo(0, 0);
    setIsVisible(true);
  }, []);

  useEffect(() => {
    const observer = new IntersectionObserver(
      (entries) => {
        entries.forEach((entry) => {
          if (entry.isIntersecting) {
            setPartnersVisible(true);
            observer.disconnect();
          }
        });
      },
      { threshold: 0.3 }
    );

    if (partnersRef.current) {
      observer.observe(partnersRef.current);
    }

    return () => observer.disconnect();
  }, []);

  return (
    <>
      {/* HERO SECTION */}
      <section
        id="home"
        className={`hero ${isVisible ? 'visible' : ''}`}
        style={{ backgroundImage: `url(${heroImage})` }}
      >
        <div className="hero-overlay"></div>
        <div className="container hero-inner">
          <div className="hero-copy fade-in-hero">
            <h1>Your Space Can Now Listen, Learn and Respond!</h1>
            <p className="lead">
              Smart home & building automation solutions that make everyday living intelligent,
              efficient and secure.
            </p>
            <Link className="btn" to="/products">
              Our Products
            </Link>
          </div>
        </div>
      </section>

      {/* FEATURES SECTION */}
      <section className={`features fade-in-section ${isVisible ? 'visible' : ''}`}>
        <div className="feature-block">
          <div className="text">
            <h1>Innovative Solutions</h1>
            <p>
              At Kilowatt Electric, we specialize in smart home and building automation solutions...
            </p>
          </div>
          <img src={Img1} alt="Modern Kitchen" />
        </div>

        <div className="feature-block reverse">
          <img src={Img2} alt="Dining Room" />
          <div className="text">
            <h1>Seamless Integration</h1>
            <p>
              Whether it’s a private home, commercial space, hotel, or healthcare facility...
            </p>
          </div>
        </div>
      </section>

      {/* PARTNERS SECTION */}
      <section
        ref={partnersRef}
        className={`partners-section fade-in-section ${partnersVisible ? 'visible' : ''}`}
      >
        <div className="container">
          <h2 className="section-title">Our Partners</h2>
          <div className="partners-grid">
            {partners.map((partner, index) => (
              <div
                key={index}
                className={`partner-card fade-in-card ${partnersVisible ? 'visible' : ''}`}
                style={{ transitionDelay: `${index * 100}ms` }}
              >
                <img src={partner.logo} alt={partner.name} />
                <h3>{partner.name}</h3>
                <p>{partner.description}</p>
                <a
                  className="know-more-btn"
                  href={partner.website}
                  target="_blank"
                  rel="noopener noreferrer"
                >
                  Know More
                </a>
              </div>
            ))}
          </div>
        </div>
      </section>
    </>
  );
}

export default Home;
